function fitStage(){const area=$('#stage-area'),frame=$('#stage-frame');if(!area||!frame)return;const css=getComputedStyle(area),availableWidth=area.clientWidth-parseFloat(css.paddingLeft)-parseFloat(css.paddingRight),availableHeight=area.clientHeight-parseFloat(css.paddingTop)-parseFloat(css.paddingBottom),ratio=ratioPortrait?9/16:16/9,width=Math.max(1,Math.min(availableWidth,900,availableHeight*ratio)),height=width/ratio;frame.style.width=`${width}px`;frame.style.height=`${height}px`;frame.style.aspectRatio=ratioPortrait?'9 / 16':'16 / 9';frame.style.transform=`scale(${stageZoom/100})`;frame.style.transformOrigin='center';}
function getBrandImage(dataUrl){if(!dataUrl)return null;if(!brandImageCache.has(dataUrl)){const image=new Image();image.onload=()=>{if(project?.brand&&(project.brand.logoDataUrl===dataUrl||project.brand.outroImageDataUrl===dataUrl))renderAll();};image.src=dataUrl;brandImageCache.set(dataUrl,image);}const image=brandImageCache.get(dataUrl);return image.complete&&image.naturalWidth?image:null;}
function drawLogo(ctx,width,height,brand){const image=getBrandImage(brand?.logoDataUrl);if(!image)return;const box=Math.min(width,height)*brand.logoSize/100,scale=Math.min(box/image.naturalWidth,box/image.naturalHeight),w=image.naturalWidth*scale,h=image.naturalHeight*scale,pad=Math.min(width,height)*.035,positions={'top-left':[pad,pad],'top-right':[width-pad-w,pad],'bottom-left':[pad,height-pad-h],'bottom-right':[width-pad-w,height-pad-h]},[x,y]=positions[brand.logoPosition]||positions['top-right'];ctx.save();ctx.globalAlpha=brand.logoOpacity;ctx.drawImage(image,x,y,w,h);ctx.restore();}
