function renderVisualDslV3At(canvas,scene,sceneTime,width,height,options){const normalized=visualDslSceneForProjectScene(scene);if(!normalized)throw new Error(`Scene ${scene.title} is not a Visual DSL v3 scene.`);const ref=scene.visualDslV3Ref,result=renderVisualDslV3Frame(canvas,project.visualDslV3,ref.variant,ref.sceneId,sceneTime,{resources:visualAssetRuntime.resources,missingAssetPolicy:'diagnostic'});drawCaption(canvas.getContext('2d'),width,height,scene,sceneTime,options.captionsEnabled,options.captionBackgroundOpacity,options.karaokeEnabled);return result.evaluated;}
function renderProjectSceneLayers(webgl,overlay,scene,sceneTime,options){if(scene.visualDslV3Ref){renderVisualDslV3At(overlay,scene,sceneTime,overlay.width,overlay.height,options);return;}if(scene.objectScene){renderSceneObjectGraph(overlay,scene,sceneTime,{...options,preparedCharacterVersions});return;}if(project.motionMode==='asset2d'&&scene.assetScene){renderSceneAsset2D(overlay,scene,sceneTime,options);return;}if(project.motionMode==='canvas2d'){renderSceneCanvas2D(overlay,scene,sceneTime,options);return;}renderSceneLayers(webgl,overlay,scene,sceneTime,options);}
function renderSceneFrameAt(ctx,webgl,overlay,scene,sceneTime,width,height){const shown=displayScene(scene),options={captionsEnabled:project.captionsEnabled,captionBackgroundOpacity:project.captionBackgroundOpacity,karaokeEnabled:project.karaokeCaptions,preparedCharacterVersions,renderPublishedSprites:true};if(shown.visualDslV3Ref){renderVisualDslV3At(ctx.canvas,shown,sceneTime,width,height,options);drawLogo(ctx,width,height,project.brand);return;}if(shown.objectScene){renderSceneObjectGraph(ctx.canvas,shown,sceneTime,options);drawLogo(ctx,width,height,project.brand);return;}if(project.motionMode==='asset2d'&&shown.assetScene){renderSceneAsset2D(ctx.canvas,shown,sceneTime,options);drawLogo(ctx,width,height,project.brand);return;}if(project.motionMode==='canvas2d'){renderSceneCanvas2D(ctx.canvas,shown,sceneTime,options);drawLogo(ctx,width,height,project.brand);return;}renderSceneLayers(webgl,overlay,shown,sceneTime,options);ctx.clearRect(0,0,width,height);ctx.drawImage(webgl,0,0);ctx.drawImage(overlay,0,0);drawLogo(ctx,width,height,project.brand);}
