function openScriptImportChoices(candidate,existingProject,{hasVariants,aspect,importedPortrait,sceneCount,generateVoices=true,syncAudio=false}){let backupReady=false,dialog;const exportBackup=()=>{try{saveProject(existingProject,projectStorageKey);const stamp=new Date().toISOString().replace(/[:.]/g,'-');downloadJson(existingProject,`project-backup-${stamp}.json`);backupReady=true;showToast('Đã xuất bản sao lưu project hiện tại.');}catch(error){showToast('Không thể tạo bản sao lưu: '+error.message);}};const requireBackup=()=>{if(backupReady)return true;showToast('Hãy tải bản sao lưu trước khi tiếp tục nhập.');return false;};const applyImported=async()=>{remember();project=candidate;sceneIndex=0;time=0;ratioPortrait=hasVariants?false:importedPortrait;if(hasVariants)persistPreferences({preferredExportRatios:'both'});else persistPreferences({preferredExportRatios:importedPortrait?'portrait':'landscape'});save();renderAll();if(syncAudio){await syncAudioSceneDurations();showToast('Đã nhập project và đồng bộ thời lượng cảnh theo audio.');return;}const pending=generateVoices&&preferences.autoVoiceAfterImport?project.scenes.map((scene,index)=>scene.narration.trim()&&scene.voice.autoGenerate?index:-1).filter(index=>index>=0):[];showToast(`Đã nhập ${sceneCount} cảnh và chỉ dẫn hoạt cảnh.${aspect==='both'?' JSON hỗ trợ cả 16:9 và 9:16; chọn “Cả 2” khi xuất.':''}${pending.length?` Đang tạo voice cho ${pending.length} cảnh…`:' Chưa tạo âm thanh.'}`,{persistent:pending.length>0});if(pending.length)generateImportedVoices(pending);};dialog=showDialog('Nhập JSON vào Motion Studio',`<p>Tệp <b>${escapeHtml(candidate.sourceFileName||'JSON')}</b> có ${sceneCount} cảnh${hasVariants?' và hai Scene Graph riêng cho 16:9/9:16':'.'} Chọn cách áp dụng. Project hiện tại vẫn được giữ cho tới khi bạn chọn thay thế.</p><p class="field-help">Tải bản sao lưu project hiện tại trước khi tiếp tục. “Tạo project mới” lưu vào một session riêng, giữ nguyên project cũ. “Thay thế” cập nhật project đang mở.</p>`,[{label:'Tải backup project hiện tại',close:false,action:exportBackup},{label:'Tạo project mới',primary:true,close:false,action:()=>{if(!requireBackup())return;const id=crypto.randomUUID(),key=`lam-motion-studio.project.v2.session.${id}`,preferenceKey=`lam-motion-studio.preferences.v1.session.${id}`,next=normalizeProject({...candidate,id});try{saveProject(next,key);if(!savePreferences({...preferences,preferredExportRatios:hasVariants?'both':importedPortrait?'portrait':'landscape'},preferenceKey))throw new Error('Không lưu được thiết lập session mới.');const url=new URL(location.href);url.searchParams.set('session',id);dialog.remove();location.assign(url.toString());}catch(error){localStorage.removeItem(key);showToast('Không thể tạo project mới: '+error.message);}}},{label:'Thay thế project hiện tại',close:false,action:()=>{if(!requireBackup())return;dialog.remove();applyImported().catch(error=>showToast('Không thể đồng bộ project đã nhập: '+error.message));}}]);}
async function generateImportedVoices(indexes){let completed=0;for(const index of indexes){const scene=project.scenes[index];if(await generateVoice(index,scene.voice.voiceId||'phuong_linh',scene.voice.rate||1))completed++;}showToast(`Đã tạo voice cho ${completed}/${indexes.length} cảnh.`);}function importAudio(file){if(!file)return;if(file.size>2*1024*1024){showToast('Audio tối đa 2 MB cho mỗi scene để project lưu được trong browser.');return;}if(!file.type.startsWith('audio/')&&!/\.(wav|mp3|m4a|ogg|webm)$/i.test(file.name)){showToast('Hãy chọn file audio WAV, MP3, M4A, OGG hoặc WebM.');return;}const reader=new FileReader();reader.onload=async()=>{try{edit({audio:{dataUrl:String(reader.result),name:file.name,mimeType:file.type||'audio/mpeg',volume:1}});await syncAudioSceneDurations();showToast('Đã gắn audio và tự khớp thời lượng cảnh theo audio.');}catch(error){showToast(`Không thể đọc audio: ${error.message}`);}};reader.readAsDataURL(file);}
async function playClip(scene){if(!scene.audio?.dataUrl)return;if(playing){playing=false;previewPlaybackGeneration++;cancelAnimationFrame(raf);$('#play-button').textContent='▶';$('#center-play').textContent='▶';}stopPreviewAudio();const generation=previewAudioGeneration;audioContext??=new AudioContext();try{await audioContext.resume();const buffer=await getPreviewBuffer(scene);if(!buffer||generation!==previewAudioGeneration)return;const source=audioContext.createBufferSource(),gain=audioContext.createGain();source.buffer=buffer;gain.gain.value=scene.audio.volume??1;source.connect(gain);gain.connect(audioContext.destination);activePreviewSources.push(source);source.onended=()=>{activePreviewSources=activePreviewSources.filter(item=>item!==source);};source.start();}catch{showToast('Browser không đọc được định dạng audio này.');}}
