 toggle.checked=preferences.promptCharacterEnabled===true;requiredMode.checked=preferences.promptCharacterUseMode==='required';requiredMode.disabled=!toggle.checked;if(['all','sprite','rigged'].includes(preferences.promptCharacterType))filter.value=preferences.promptCharacterType;
