 requiredMode.onchange=()=>persistPreferences({promptCharacterUseMode:requiredMode.checked?'required':'auto'});
 filter.onchange=()=>{persistPreferences({promptCharacterType:filter.value});fillCharacters();};search.oninput=fillCharacters;
 character.onchange=()=>{version.replaceChildren(new Option('Choose exact published version',''));for(const item of versionsFor(character.value))version.add(new Option(`${item.published_version} · ${item.character_type} · ${item.published_checksum.slice(0,12)}…`,item.character_id+'@'+item.published_version));};
 version.onchange=()=>{const capability=catalog?.capabilities.find(item=>item.character_id+'@'+item.published_version===version.value)||null;summary.textContent=capability?`${capability.display_name} · ${capability.character_type} · v${capability.published_version}\n${capability.character_type==='sprite'?'Poses: '+capability.available_poses.map(x=>x.pose_id).join(', ')+'; Clips: '+capability.available_clips.map(x=>x.clip_id).join(', '):'Rigged actions: '+capability.available_motions.join(', ')}\nChecksum: ${capability.published_checksum}`:'Choose a verified exact Published Version.';};
 add.onclick=()=>{const capability=catalog?.capabilities.find(item=>item.character_id+'@'+item.published_version===version.value);if(!capability)return;if(cast.some(item=>item.character_id===capability.character_id&&item.published_version===capability.published_version)){status.textContent='This exact character/version is already in the selected cast.';return;}if(cast.length>=5){status.textContent='Selected cast limit is 5 Published Character versions.';return;}cast.push({character_id:capability.character_id,published_version:capability.published_version,capability,role_hint:''});renderCast();summary.textContent='Added '+capability.display_name+' · v'+capability.published_version;};
 retry.onclick=loadCatalog;panel.hidden=!toggle.checked;if(toggle.checked)loadCatalog();
