function videoFilenameBase(){const source=String(project.sourceFileName||''),dot=source.lastIndexOf('.'),imported=dot>0?source.slice(0,dot):source,base=imported||String(project.title||'video').toLowerCase().replace(/[^a-z0-9]+/g,'-'),invalid='<>:"/|?*'+String.fromCharCode(92);return [...base].map(char=>invalid.includes(char)?'-':char).join('').replace(/\s+/g,' ').replace(/[. ]+$/,'').trim()||'video';}function showExportDownloads(format){const panel=$('#export-downloads');for(const [key,label,aspect] of [['landscape','Tải video 16:9','16:9'],['portrait','Tải video 9:16','9:16']]){const available=Boolean(exportVideoUrls[key]);const button=panel.querySelector(`[data-download="${key}"]`);button.onclick=()=>{const link=document.createElement('a');link.href=exportVideoUrls[key];link.download=`${videoFilenameBase()}-${aspect.replace(':','x')}.${format==='webm'?'webm':'mp4'}`;link.click();};button.disabled=!available;button.hidden=!available;button.textContent=label;}panel.hidden=false;}
