$('#undo-button').onclick=()=>{if(!history.length)return;future.push(copyProject(project));project=history.pop();save();renderAll();};$('#redo-button').onclick=()=>{if(!future.length)return;history.push(copyProject(project));project=future.pop();save();renderAll();};
$('#tracks').addEventListener('pointerdown',e=>{if(e.target.closest('.clip'))return;const bounds=$('#tracks').getBoundingClientRect(),fraction=clamp((e.clientX-bounds.left-82)/(bounds.width-82),0,1);seekTo(fraction*duration());});
window.addEventListener('keydown',e=>{if(e.code==='Space'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();togglePlayback();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();exportProject();}});
new ResizeObserver(()=>fitStage()).observe($('#stage-area'));
const exportProgressPanel=$('#export-progress');restoreFloatingPosition(exportProgressPanel,'exportProgressPosition');enableFloatingDrag(exportProgressPanel,exportProgressPanel.querySelector('.export-progress-heading'),'exportProgressPosition');save();renderAll();if(project.scenes.some(scene=>scene.audio?.dataUrl))syncAudioSceneDurations().catch(error=>showToast('Không thể đọc thời lượng audio: '+error.message));
let activeWorkspace='video';const videoWorkspace=document.querySelector('.workspace'),characterWorkspace=$('#character-studio-workspace'),bottomBar=document.querySelector('.bottom-bar'),videoOnlyElements=[...document.querySelectorAll('.project-name,.top-actions,#export-downloads')];
function switchWorkspace(name){if(name===activeWorkspace)return true;if(activeWorkspace==='character'&&characterStudioManager&&!characterStudioManager.confirmDiscard())return false;activeWorkspace=name;const isCharacter=name==='character';videoWorkspace.hidden=isCharacter;characterWorkspace.hidden=!isCharacter;bottomBar.hidden=isCharacter;document.querySelector('.app-shell').classList.toggle('character-studio-active',isCharacter);document.body.classList.toggle('character-studio-active',isCharacter);for(const element of videoOnlyElements)element.hidden=isCharacter;document.querySelectorAll('.workspace-switch-button').forEach(button=>{const active=button.dataset.workspace===name;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));});if(isCharacter&&!characterStudioManager){characterStudioManager=initializeCharacterStudio(characterWorkspace);characterStudioManager?.ready.catch(error=>console.error('Character Studio initialization failed:',error));}return true;}
document.querySelectorAll('.workspace-switch-button').forEach(button=>button.addEventListener('click',()=>switchWorkspace(button.dataset.workspace)));
window.addEventListener('beforeunload',event=>{if(activeWorkspace==='character'&&characterStudioManager?.isDirty()){event.preventDefault();event.returnValue='';}});
